#!/usr/bin/env python3
"""Rebuild the one transport segment that is intentionally stored as short literals."""
from __future__ import annotations

import hashlib
from pathlib import Path

PARTS = (
    "",
    "",
    "",
    "",
)

payload = "".join(PARTS)
if len(payload) != 4000:
    raise SystemExit(f"unexpected payload length: {len(payload)}")
if hashlib.sha1((f"blob {len(payload)}\0" + payload).encode()).hexdigest() != "c27c63db9df32ca9a4fc425e388226ac2e2f7877":
    raise SystemExit("transport segment checksum mismatch")
Path("/tmp/gmd-event-part-01b").write_text(payload, encoding="ascii")
